{
  "technical_and_design_decisions": [
    "For U1, implement transaction context as a per-transaction object instance in the Java chaincode shim to ensure thread safety, passed to contract methods similarly to Node.js.",
    "For U2/U3, move the Go package protos/utils to a new protoutils package, updating all internal imports and build scripts while keeping generated code separate.",
    "For U4, backport the existing Kafka health check feature from the master branch to the Fabric 1.4 LTS branch with minimal modifications for compatibility.",
    "For U5, implement an explicit read-only invoke path (e.g., a query-only invocation type) that only allows ledger Gets and can be called by channel Readers, rather than dynamic per-operation access checks.",
    "For U6, introduce a new peer configuration option (e.g., peer.discovery.externalEndpoint) that overrides the address advertised via service discovery, independent of PEER_GOSSIP_EXTERNALENDPOINT.",
    "For U7, expose a new operations service HTTP endpoint /version on both peer and orderer returning version metadata.",
    "For U8, rewrite existing official Go samples (e.g., fabcar, basic chaincode) using idiomatic Go patterns while preserving functionality."
  ],
  "assumptions": [
    "U2 and U3 are duplicate requirements and are counted as a single refactoring task.",
    "The developer is experienced with Hyperledger Fabric, Go, and Java, and has a working build environment; no onboarding time is included.",
    "Only the components explicitly mentioned are in scope; Node.js already provides transaction context and needs no changes for U1.",
    "The explicit read-only invoke solution for U5 is acceptable and does not require broader endorsement policy redesign.",
    "The set of Go samples to update for U8 is limited to the official Fabric sample chaincodes and simple application examples.",
    "Effort estimates reflect personal development, unit testing, and integration work only; they exclude third-party code review, CI queue time, and release management beyond documentation.",
    "Backporting U4 assumes the master branch health check code is largely compatible with 1.4 Kafka consensus."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement Java chaincode transactional context (U1)",
      "activity_description": "Design and implement per-transaction context object in Java chaincode shim, providing access to stub and APIs, with thread-safety and unit tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "Refactor protos/utils to protoutils (U2/U3)",
      "activity_description": "Create protoutils Go package, move code from protos/utils, update all imports and build configuration, and verify build/tests.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "Backport Kafka health checks to 1.4 LTS (U4)",
      "activity_description": "Identify Kafka health check commits in master, adapt and port them to the Fabric 1.4 LTS branch, and validate with tests.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A4",
      "activity_name": "Enable read-only chaincode invoke for channel Readers (U5)",
      "activity_description": "Design and implement a read-only invocation path that permits channel Readers to query ledger data, including access control changes, peer/endorser updates, and tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A5",
      "activity_name": "Configurable external endpoint for service discovery (U6)",
      "activity_description": "Add new peer configuration for external discovery endpoint, propagate via gossip/service discovery, and test with discovery flows.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "Operations service version endpoint (U7)",
      "activity_description": "Implement /version endpoint in the operations service for both peer and orderer, returning version info, with unit and integration tests.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A7",
      "activity_name": "Rewrite Go samples idiomatically (U8)",
      "activity_description": "Update official Go chaincode and application samples to use idiomatic Go style, ensuring examples remain functional.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "Integration testing and verification",
      "activity_description": "Build the complete increment, perform end-to-end and integration tests across all changes, and fix defects found.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A9",
      "activity_name": "Documentation and release notes",
      "activity_description": "Update user documentation, configuration references, sample READMEs, and release notes for all new features and refactoring.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 164
  }
}

